CREATE TABLE author (id INT GENERATED BY DEFAULT AS IDENTITY (START WITH 1) PRIMARY KEY, name VARCHAR(100) NOT NULL);
CREATE TABLE book (id INT GENERATED BY DEFAULT AS IDENTITY (START WITH 1) PRIMARY KEY, author_id INT NOT NULL, title VARCHAR(200) NOT NULL, isbn VARCHAR(20) NOT NULL UNIQUE, price DECIMAL(8,2) NOT NULL, stock INT NOT NULL, FOREIGN KEY (author_id) REFERENCES author(id));
CREATE TABLE review (id INT GENERATED BY DEFAULT AS IDENTITY (START WITH 1) PRIMARY KEY, book_id INT NOT NULL, rating INT NOT NULL, comment VARCHAR(500), FOREIGN KEY (book_id) REFERENCES book(id));
